const VISUALS=[["Inside the rover", "The controller interprets inputs. Motors turn electrical commands into movement.", "Exploded conceptual view separating the controller and distance sensor from the rover chassis."], ["Two motors. One direction.", "Compare the wheel commands, then measure what the rover actually does.", "Rover with drive wheels separated slightly to reveal the motors, beside forward markers."], ["Design around the parcel", "A light, removable cradle leaves the sensor, wheels and controls clear.", "Cargo parcel lifted above its paper cradle, with paper prototype pieces alongside the rover."], ["Measure before you trust", "Compare the sensor reading with a ruler and a wide, upright target.", "Rover facing a cardboard target with a measuring strip along the test lane."], ["Plan a route, then test it", "A sequence can describe a path. Timed motors still need calibration.", "Delivery rover at the start of an L-shaped floor route ending in a yellow delivery bay."], ["Leave room to stop", "Set a threshold, use low speed, and measure the real stopping gap.", "Rover approaching a cardboard obstacle with a red stopping boundary on the floor."], ["Bring the parts together", "The delivery must keep the parcel, reach the bay, and avoid contact.", "Loaded delivery rover inside a taped green bay with a cardboard stopping target ahead."], ["Show the evidence", "A final demonstration is stronger when you can explain the trial record.", "Finished rover beside a blank engineering log clipboard."]];
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let activeLesson=1, program=[],state=Rover.initial(),timer=null,trials=[],prediction='';
function download(name,text,type='text/plain'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function showView(name){if(name!=='course')document.querySelectorAll('audio').forEach(a=>a.pause());document.querySelectorAll('main>section').forEach(s=>s.hidden=s.id!==name+'-view');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name!=='lab')pause();}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
$('#missions').innerHTML=COURSE.lessons.map(l=>`<button class="mission" data-lesson="${l.id}"><img class="mission-image" src="images/mission-${l.id}.jpg" alt="${VISUALS[l.id-1][2]}" loading="lazy"><span class="eyebrow">MISSION ${String(l.id).padStart(2,'0')}</span><h3>${l.title}</h3><p>${l.mission}</p><span>Open interactive lesson →</span></button>`).join('');
document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{renderLesson(+b.dataset.lesson);$('#lesson').focus();});
function renderLesson(id){activeLesson=id;const l=COURSE.lessons[id-1];$('#lesson').innerHTML=`<div class="section-label">MISSION ${id} · TWO 45-MINUTE SESSIONS</div><h2>${l.title}</h2><p class="lead">${l.mission}</p><section id="interactive-slides" class="lesson-player" aria-label="Interactive lesson slides"></section><details class="lesson-reference"><summary>Full lesson reference and downloads</summary><figure class="lesson-visual"><img src="images/mission-${id}.jpg" alt="${VISUALS[id-1][2]}"><figcaption><span class="eyebrow">LOOK CLOSER</span><h3>${VISUALS[id-1][0]}</h3><p>${VISUALS[id-1][1]}</p><small>Concept illustration. Follow the kit guide for actual assembly.</small></figcaption></figure><div class="note"><strong>Your learning target</strong><p>${l.objective}</p></div><div class="cols"><div><h3>The idea</h3><p>${l.concept}</p><h3>Build & test</h3><ol>${l.build.map(s=>`<li>${s}</li>`).join('')}</ol></div><aside><h3>On your workbench</h3><p>${l.parts}</p><h3>What counts as success?</h3><p>${l.success}</p><h3>Make it a fair test</h3><p>${l.variables}</p><a class="btn primary" href="code/lesson-${id}.ts" download>Download starter program</a><p class="small">Add Kitronik’s extension in MakeCode first. Teacher hardware pretest required.</p><h3>Listen to Amy</h3><audio controls preload="none" src="audio/lesson-${id}.wav">${l.narration}</audio><details><summary>Narration transcript</summary><p>${l.narration}</p></details></aside></div><div class="cols"><div class="note"><h3>Pause & explain</h3><p>${l.question}</p><details><summary>Check your reasoning</summary><p>${l.answer}</p></details></div><div><h3>If it doesn’t work</h3><p>${l.fix}</p><p><strong>Watch for this:</strong> ${l.misconception}</p><details><summary>Take it further</summary><p>${l.extend}</p></details></div></div><div class="actions"><a class="btn" href="student-workbook.pdf">Open engineering workbook</a><button class="btn" id="to-lab">Try the Mission Lab →</button>${id<8?'<button class="btn primary" id="next">Next mission →</button>':''}</div></details>`;LessonPlayer.mount($('#interactive-slides'),id);$('#to-lab').onclick=()=>showView('lab');if($('#next'))$('#next').onclick=()=>{renderLesson(id+1);$('#lesson').focus();};document.querySelectorAll('[data-lesson]').forEach(b=>b.classList.toggle('selected',+b.dataset.lesson===id));}
$('#teacher-view').innerHTML=`<div class="section-label">READY FOR YOUR CLASSROOM</div><h1>The teacher workbench</h1><p class="lead">A complete teaching draft with reproducible tasks and evidence-based assessment. Pretest the programs on your kit before teaching.</p><div class="actions"><a class="btn primary" href="teacher-guide.pdf">Teacher guide & answer key</a><a class="btn" href="student-workbook.pdf">Student workbook</a><a class="btn" href="starter-programs.zip">All 8 starter programs</a></div><h2>Set up the room</h2><ol>${COURSE.setup.map(s=>`<li>${s}</li>`).join('')}</ol><h2>Two sessions per mission</h2>${COURSE.routine.map(s=>`<p>${s}</p>`).join('')}<h2>Assess the engineering</h2><p>Look for a clear requirement, an explained program, repeatable tests, and a justified revision. Use the four-level rubric in the teacher guide.</p><h2>A closer look at your rover</h2><video controls preload="metadata" poster="rover.png" style="width:100%;max-width:850px;border-radius:20px"><source src="rover-tour.mp4" type="video/mp4"></video><p class="small">A four-second model tour. No sound. The blue board is the controller; the two front circles represent the ultrasonic sensor; the side wheels are motor-driven; the upper tray carries the paper parcel.</p><h2>Rover anatomy</h2><img src="rover.png" alt="Conceptual rover: yellow chassis, blue controller, front ultrasonic sensor, two drive wheels, and a lightweight cargo cradle" style="width:100%;max-width:850px;border-radius:24px"><p class="small">Original Blender illustration. Conceptual arrangement; use the manufacturer’s assembly guide for the actual kit.</p><h2>Sources & credits</h2><ul>${COURSE.sources.map(s=>`<li><a href="${s[1]}" target="_blank" rel="noopener">${s[0]}</a></li>`).join('')}</ul><p>Narration synthesized with Amy Sullivan’s own voice profile. Content and reference programs are newly authored teaching materials. The grid simulator is a logic model, not a physics model or a kit emulator. No physical-robot or classroom test is claimed.</p>`;
$('#lab-view').innerHTML=`<div class="section-label">PLAN · PREDICT · TEST · IMPROVE</div><h1>Delivery Rover Mission Lab</h1><p class="lead">Write a route. Explain a decision. Learn from the run.</p><div class="note">This grid models program logic: every move is one cell and each turn is exactly 90°. Real motors, distances, sensor readings, and braking need physical calibration.</div><div class="lab-grid"><section class="panel"><label for="map"><strong>Choose a mission</strong></label><select id="map">${Rover.maps.map((m,i)=>`<option value="${i}">${i+1}. ${m.name}</option>`).join('')}</select><div id="board" class="board" role="img" aria-label="Eight by eight delivery route"></div><p class="small">▲ rover · S start · ★ delivery bay · dark squares are walls. North is up.</p><div id="status" class="status" role="status" aria-live="polite"></div><div class="actions"><button class="btn primary" id="run">Run</button><button class="btn" id="step">Step</button><button class="btn" id="pause">Pause</button><button class="btn" id="reset">Reset rover</button></div></section><section class="panel"><h2>Your program</h2><p>Click to add commands. Use the arrows to reorder them. Maximum 40 commands.</p><div class="actions">${Object.entries(Rover.labels).map(([k,v])=>`<button class="btn mini" data-add="${k}">${v}</button>`).join('')}</div><ol id="program" class="program"></ol><button class="btn" id="clear">Clear program</button><label for="prediction"><h3>Predict before you run</h3></label><textarea id="prediction" rows="3" placeholder="Where will the rover finish? What will its sensor decide?"></textarea><details><summary>Need a starting hint?</summary><p id="hint"></p></details></section></div><section class="panel"><h2>Evidence from this run</h2><div style="overflow:auto"><table><thead><tr><th>Step</th><th>Command</th><th>Sensor ahead</th><th>Position (x,y)</th><th>Heading</th></tr></thead><tbody id="trace"></tbody></table></div><div class="actions"><button class="btn" id="record">Record trial</button><button class="btn" id="export">Download trial log</button></div><p id="trial-count">No trials recorded yet.</p><p class="small">Trials stay in this open page. Download your log before closing or refreshing. No student data is sent to a server.</p></section>`;
function pause(){if(timer)clearInterval(timer);timer=null;}
function reset(){pause();state=Rover.initial(+$('#map').value);draw();}
function draw(){const m=Rover.maps[state.map];$('#board').innerHTML=Array.from({length:64},(_,i)=>{const x=i%8,y=Math.floor(i/8),bot=x===state.x&&y===state.y,wall=m.walls.some(p=>p[0]===x&&p[1]===y),goal=x===m.goal[0]&&y===m.goal[1],start=x===m.start[0]&&y===m.start[1];return `<div class="cell ${wall?'wall':''} ${goal?'goal':''} ${start?'start':''}" title="Column ${x}, row ${y}${wall?', wall':''}${goal?', delivery bay':''}">${bot?`<span class="bot" style="display:inline-block;transform:rotate(${state.h*90}deg)">▲</span>`:goal?'★':start?'S':''}</div>`;}).join('');$('#board').setAttribute('aria-label',`8 by 8 grid. Rover column ${state.x}, row ${state.y}, facing ${['north','east','south','west'][state.h]}. Delivery bay ${m.goal.join(', ')}. Sensor ahead ${Rover.blocked(state)?'blocked':'clear'}.`);$('#status').textContent=state.message;$('#hint').textContent=m.hint;$('#program').innerHTML=program.map((c,i)=>`<li ${i===state.pc&&state.status==='running'?'aria-current="step"':''}>${Rover.labels[c]} <button class="mini" data-up="${i}" aria-label="Move command ${i+1} up" ${i===0?'disabled':''}>↑</button> <button class="mini" data-down="${i}" aria-label="Move command ${i+1} down" ${i===program.length-1?'disabled':''}>↓</button> <button class="mini" data-remove="${i}" aria-label="Remove command ${i+1}">×</button></li>`).join('')||'<p>Add your first command above.</p>';$('#trace').innerHTML=state.trace.map(t=>`<tr><td>${t.step}</td><td>${t.command}</td><td>${t.sensor}</td><td>${t.x}, ${t.y}</td><td>${t.heading}</td></tr>`).join('');document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{program.splice(+b.dataset.remove,1);reset();});for(const dir of ['up','down'])document.querySelectorAll(`[data-${dir}]`).forEach(b=>b.onclick=()=>{let i=+b.dataset[dir],j=i+(dir==='up'?-1:1);[program[i],program[j]]=[program[j],program[i]];reset();});}
function advance(){if(!program.length){$('#status').textContent='Add a command before running.';pause();return;}state=Rover.step(state,program);draw();if(state.status!=='running')pause();}
document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{if(program.length>=40){$('#status').textContent='Maximum 40 commands. Revise or remove a command.';return;}program.push(b.dataset.add);reset();});$('#map').onchange=()=>{program=[];reset();};$('#run').onclick=()=>{pause();if(['finished','collision','stopped'].includes(state.status))state=Rover.initial(state.map);advance();if(state.status==='running')timer=setInterval(advance,650);};$('#step').onclick=()=>{pause();advance();};$('#pause').onclick=()=>{pause();$('#status').textContent='Paused. Step or run to continue.';};$('#reset').onclick=reset;$('#clear').onclick=()=>{program=[];reset();};$('#record').onclick=()=>{if(!state.steps){$('#status').textContent='Run at least one command before recording evidence.';return;}trials.push({trial:trials.length+1,mission:Rover.maps[state.map].name,prediction:$('#prediction').value,program:program.join(' '),status:state.status,success:Rover.atGoal(state)&&['finished','stopped'].includes(state.status),steps:state.steps,x:state.x,y:state.y});$('#trial-count').textContent=`${trials.length} trial(s) recorded. Download your log before leaving.`;};$('#export').onclick=()=>{if(!trials.length){$('#trial-count').textContent='Record a trial first.';return;}const keys=Object.keys(trials[0]),quote=v=>'"'+String(v).replace(/"/g,'""')+'"';download('rover-trial-log.csv',[keys.join(','),...trials.map(t=>keys.map(k=>quote(t[k])).join(','))].join('\r\n'),'text/csv');};
renderLesson(1);draw();
if(navigator.modelContext?.registerTool){try{navigator.modelContext.registerTool({name:'read_rover_lab',description:'Read the current educational rover simulator state and program. Does not change the course.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:async()=>({content:[{type:'text',text:JSON.stringify({state,program})}]})});}catch(e){console.info('Optional course tool registration unavailable.');}}

